@push('scripts')<script>$(function(){var t=$('#tax-report-table'),p=$('#tax-period'),b=$('#tax-basis'),x=$.fn.dataTable.render.text(),dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.period_id=p.val();d.date_basis=b.val()},dataSrc:function(r){$.each(r.totals||{},function(k,v){$('[data-total="'+k+'"]').text(v||'0.00')});return r.data}},order:[[0,'asc']],buttons:[window.erpExcelButton(t,function(){return{period_id:p.val(),date_basis:b.val()}})],columns:[{data:null,name:'journal_entry_lines.tax_point_date',render:function(v,type,row){return type==='display'?x.display(b.val()==='TAX_POINT'?row.tax_point_date_label:row.tax_settlement_date_label):b.val()==='TAX_POINT'?row.tax_point_date:row.tax_settlement_date}},{data:'entry_number',name:'entries.entry_number',render:x.display},{data:'tax_code',name:'tax_codes.code',render:x.display},{data:'tax_kind',name:'tax_codes.kind',render:x.display},{data:null,name:'accounts.code',render:function(v,type,row){return type==='display'?x.display(row.account_code+' · '+row.account_name):v}},{data:'tax_base',name:'journal_entry_lines.tax_base',className:'text-end',render:x.display},{data:'tax_amount',name:'journal_entry_lines.tax_amount',className:'text-end',render:x.display},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,type,row){return type==='display'?'<a class="btn btn-sm btn-outline-dark" href="'+x.display(row.entry_url)+'">ดู</a>':'';}}]}));p.add(b).on('change',function(){dt.ajax.reload()})});</script>@endpush
